    public IReadOnlyCollection<ZeroPhpCutoverAssignment> GetBatch(int batchNumber)
        => Assignments.Where(item => item.BatchNumber == batchNumber).ToArray();

    public IReadOnlyCollection<int> BatchNumbers
        => Assignments.Select(item => item.BatchNumber).Distinct().Order().ToArray();
